import React from 'react';
import './Comments.css';



function Comments( id, photo, name, text) {

    return (
        <div className='Comments'>
                <div className='comments'>
                    <img src={photo} alt=" " />
                    <div className='info'>
                        <span>{name}</span>
                        <p>{text}</p>
                    </div>
               </div>
         
        </div>
    );
}
export default Comments;
